{
  "root": "main_stack",
  "state": {
    "additional_requirements": [
      {
        "item": "Dependents",
        "details": "Marriage/birth certificates for spouse/children, their passports, and proof of funds."
      },
      {
        "item": "ATAS Certificate",
        "details": "If your job involves sensitive subjects, you may need an Academic Technology Approval Scheme (ATAS) certificate."
      },
      {
        "item": "Professional Registration",
        "details": "For certain professions (e.g., doctors, nurses), proof of registration with the relevant UK professional body."
      },
      {
        "item": "Translation of Documents",
        "details": "Any document not in English or Welsh must be accompanied by a certified translation."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "overview_title",
        "overview_text",
        "checklist_section_title",
        "checklist_icon_and_label_stack",
        "checklist_intro_text",
        "document_list_stack",
        "additional_req_title",
        "additional_req_list_stack",
        "resources_title",
        "resources_icon_and_label_stack",
        "resources_buttons_stack",
        "guidance_sources_title",
        "guidance_sources_buttons_stack"
      ]
    },
    "overview_title": {
      "type": "Text",
      "props": {
        "text": "UK Skilled Worker Visa Application Overview",
        "variant": "h2"
      },
      "children": []
    },
    "overview_text": {
      "type": "Text",
      "props": {
        "text": "Applying for a UK Skilled Worker Visa as a non-EU citizen in Q4 2024 requires a comprehensive set of documents to demonstrate eligibility under the UK's points-based immigration system. This checklist outlines the core requirements based on current guidance."
      },
      "children": []
    },
    "checklist_section_title": {
      "type": "Text",
      "props": {
        "text": "Core Application Document Checklist",
        "variant": "h2"
      },
      "children": []
    },
    "checklist_icon_and_label_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "checklist_icon",
        "checklist_icon_label"
      ]
    },
    "checklist_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000514_01_1_file-earmark-text.svg"
      },
      "children": []
    },
    "checklist_icon_label": {
      "type": "Text",
      "props": {
        "text": "Document Checklist"
      },
      "children": []
    },
    "checklist_intro_text": {
      "type": "Text",
      "props": {
        "text": "To ensure a smooth application process, gather the following essential documents:"
      },
      "children": []
    },
    "document_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "doc_passport",
        "doc_prev_passports",
        "doc_cos",
        "doc_job_offer",
        "doc_academic_qual",
        "doc_cv",
        "doc_english_prof",
        "doc_financial_maint",
        "doc_tb_test",
        "doc_criminal_record",
        "doc_biometric"
      ]
    },
    "doc_passport": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "doc_passport_title",
        "doc_passport_desc"
      ]
    },
    "doc_passport_title": {
      "type": "Text",
      "props": {
        "text": "Valid Passport",
        "variant": "label"
      },
      "children": []
    },
    "doc_passport_desc": {
      "type": "Text",
      "props": {
        "text": "Your current passport must be valid for at least six months beyond your intended stay and have blank pages for a visa."
      },
      "children": []
    },
    "doc_prev_passports": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "doc_prev_passports_title",
        "doc_prev_passports_desc"
      ]
    },
    "doc_prev_passports_title": {
      "type": "Text",
      "props": {
        "text": "Previous Passports",
        "variant": "label"
      },
      "children": []
    },
    "doc_prev_passports_desc": {
      "type": "Text",
      "props": {
        "text": "Any expired passports you have held."
      },
      "children": []
    },
    "doc_cos": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "doc_cos_title",
        "doc_cos_desc"
      ]
    },
    "doc_cos_title": {
      "type": "Text",
      "props": {
        "text": "Certificate of Sponsorship (CoS) Reference Number",
        "variant": "label"
      },
      "children": []
    },
    "doc_cos_desc": {
      "type": "Text",
      "props": {
        "text": "This unique reference number is provided by your UK sponsoring employer. It confirms your job offer and details."
      },
      "children": []
    },
    "doc_job_offer": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "doc_job_offer_title",
        "doc_job_offer_desc"
      ]
    },
    "doc_job_offer_title": {
      "type": "Text",
      "props": {
        "text": "Job Offer Letter",
        "variant": "label"
      },
      "children": []
    },
    "doc_job_offer_desc": {
      "type": "Text",
      "props": {
        "text": "An official letter from your UK employer outlining your role, salary, start date, and other employment terms."
      },
      "children": []
    },
    "doc_academic_qual": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "doc_academic_qual_title",
        "doc_academic_qual_desc"
      ]
    },
    "doc_academic_qual_title": {
      "type": "Text",
      "props": {
        "text": "Academic Qualifications",
        "variant": "label"
      },
      "children": []
    },
    "doc_academic_qual_desc": {
      "type": "Text",
      "props": {
        "text": "Original certificates and transcripts for your relevant degrees, diplomas, or professional qualifications."
      },
      "children": []
    },
    "doc_cv": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "doc_cv_title",
        "doc_cv_desc"
      ]
    },
    "doc_cv_title": {
      "type": "Text",
      "props": {
        "text": "Curriculum Vitae (CV)/Resume",
        "variant": "label"
      },
      "children": []
    },
    "doc_cv_desc": {
      "type": "Text",
      "props": {
        "text": "An up-to-date document detailing your education and work history."
      },
      "children": []
    },
    "doc_english_prof": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "doc_english_prof_title",
        "doc_english_prof_desc"
      ]
    },
    "doc_english_prof_title": {
      "type": "Text",
      "props": {
        "text": "English Language Proficiency",
        "variant": "label"
      },
      "children": []
    },
    "doc_english_prof_desc": {
      "type": "Text",
      "props": {
        "text": "Proof of English language ability, typically through an approved test (e.g., IELTS, PTE) or an academic qualification taught in English."
      },
      "children": []
    },
    "doc_financial_maint": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "doc_financial_maint_title",
        "doc_financial_maint_desc"
      ]
    },
    "doc_financial_maint_title": {
      "type": "Text",
      "props": {
        "text": "Financial Maintenance (Funds)",
        "variant": "label"
      },
      "children": []
    },
    "doc_financial_maint_desc": {
      "type": "Text",
      "props": {
        "text": "Evidence that you have sufficient funds to support yourself in the UK (e.g., bank statements) or a sponsorship declaration from your employer."
      },
      "children": []
    },
    "doc_tb_test": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "doc_tb_test_title",
        "doc_tb_test_desc"
      ]
    },
    "doc_tb_test_title": {
      "type": "Text",
      "props": {
        "text": "Tuberculosis (TB) Test Certificate",
        "variant": "label"
      },
      "children": []
    },
    "doc_tb_test_desc": {
      "type": "Text",
      "props": {
        "text": "Required if you are applying from a country where TB screening is mandatory."
      },
      "children": []
    },
    "doc_criminal_record": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "doc_criminal_record_title",
        "doc_criminal_record_desc"
      ]
    },
    "doc_criminal_record_title": {
      "type": "Text",
      "props": {
        "text": "Criminal Record Certificate",
        "variant": "label"
      },
      "children": []
    },
    "doc_criminal_record_desc": {
      "type": "Text",
      "props": {
        "text": "From any country you have lived in for 12 months or more over the last 10 years, if requested."
      },
      "children": []
    },
    "doc_biometric": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "doc_biometric_title",
        "doc_biometric_desc"
      ]
    },
    "doc_biometric_title": {
      "type": "Text",
      "props": {
        "text": "Biometric Information",
        "variant": "label"
      },
      "children": []
    },
    "doc_biometric_desc": {
      "type": "Text",
      "props": {
        "text": "Fingerprints and a photograph taken at a visa application centre."
      },
      "children": []
    },
    "additional_req_title": {
      "type": "Text",
      "props": {
        "text": "Additional Requirements & Considerations",
        "variant": "h2"
      },
      "children": []
    },
    "additional_req_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "additional_req_intro_text",
        "additional_req_table"
      ]
    },
    "additional_req_intro_text": {
      "type": "Text",
      "props": {
        "text": "Depending on your specific circumstances, you may also need:"
      },
      "children": []
    },
    "additional_req_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "item",
            "label": "Item"
          },
          {
            "key": "details",
            "label": "Details"
          }
        ],
        "statePath": "/additional_requirements",
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "resources_title": {
      "type": "Text",
      "props": {
        "text": "Key Resources",
        "variant": "h2"
      },
      "children": []
    },
    "resources_icon_and_label_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "resources_icon",
        "resources_icon_label"
      ]
    },
    "resources_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000514_01_1_info-circle.svg"
      },
      "children": []
    },
    "resources_icon_label": {
      "type": "Text",
      "props": {
        "text": "Helpful Links"
      },
      "children": []
    },
    "resources_buttons_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_gov_uk_visa",
        "button_ukcisa"
      ]
    },
    "button_gov_uk_visa": {
      "type": "Button",
      "props": {
        "label": "Apply for a UK visa (Gov.uk)"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.gov.uk/apply-to-come-to-uk"
          }
        }
      }
    },
    "button_ukcisa": {
      "type": "Button",
      "props": {
        "label": "UKCISA - International Student Advice"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ukcisa.org.uk/"
          }
        }
      }
    },
    "guidance_sources_title": {
      "type": "Text",
      "props": {
        "text": "Official Guidance Sources",
        "variant": "h2"
      },
      "children": []
    },
    "guidance_sources_buttons_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_home_office_guidance",
        "button_skilled_worker_guidance"
      ]
    },
    "button_home_office_guidance": {
      "type": "Button",
      "props": {
        "label": "Home Office Immigration Rules"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.gov.uk/guidance/immigration-rules"
          }
        }
      }
    },
    "button_skilled_worker_guidance": {
      "type": "Button",
      "props": {
        "label": "Skilled Worker Visa Guidance"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.gov.uk/skilled-worker-visa"
          }
        }
      }
    }
  }
}
